  ('spk-ja-n5-24-naru-s3', 'spk-ja-n5-24-naru', 3, 'explain', 'With a describing word that ends in {い}, drop the {い} and add {く}. {おおきい} becomes {おおきくなります}, "it gets big."', NULL, NULL, NULL),
  ('spk-ja-n5-24-naru-s4', 'spk-ja-n5-24-naru', 4, 'prompt', 'How would you say "It gets big"?', '大きくなります。', 'おおきく なります。', NULL),
  ('spk-ja-n5-24-naru-s5', 'spk-ja-n5-24-naru', 5, 'prompt', 'How would you say "It gets small"?', '小さくなります。', 'ちいさく なります。', NULL),
  ('spk-ja-n5-24-naru-s6', 'spk-ja-n5-24-naru', 6, 'prompt', 'How would you say "It gets expensive"?', '高くなります。', 'たかく なります。', NULL),
  ('spk-ja-n5-24-naru-s7', 'spk-ja-n5-24-naru', 7, 'prompt', 'How would you say "It gets delicious"?', 'おいしくなります。', 'おいしく なります。', NULL),
  ('spk-ja-n5-24-naru-s8', 'spk-ja-n5-24-naru', 8, 'explain', 'Describing words like {きれい} and {しずか} take {に}, the same as a noun. {きれいになります}.', NULL, NULL, NULL),
  ('spk-ja-n5-24-naru-s9', 'spk-ja-n5-24-naru', 9, 'prompt', 'How would you say "It gets pretty"?', 'きれいになります。', 'きれい に なります。', NULL),
  ('spk-ja-n5-24-naru-s10', 'spk-ja-n5-24-naru', 10, 'prompt', 'How would you say "It gets quiet"?', 'しずかになります。', 'しずか に なります。', NULL),
  ('spk-ja-n5-24-naru-s11', 'spk-ja-n5-24-naru', 11, 'explain', 'For the past, {なりました}. "It became."', NULL, NULL, NULL),
  ('spk-ja-n5-24-naru-s12', 'spk-ja-n5-24-naru', 12, 'prompt', 'How would you say "It became big"?', '大きくなりました。', 'おおきく なりました。', NULL),
  ('spk-ja-n5-24-naru-s13', 'spk-ja-n5-24-naru', 13, 'prompt', 'How would you say "The dog became big"?', 'いぬは大きくなりました。', 'いぬ わ おおきく なりました。', NULL),
  ('spk-ja-n5-24-naru-s14', 'spk-ja-n5-24-naru', 14, 'prompt', 'How would you say "The restaurant became expensive"?', 'レストランは高くなりました。', 'レストラン わ たかく なりました。', NULL),
  ('spk-ja-n5-24-naru-s15', 'spk-ja-n5-24-naru', 15, 'prompt', 'How would you say "The TV became expensive"?', 'テレビは高くなりました。', 'テレビ わ たかく なりました。', NULL),
  ('spk-ja-n5-24-naru-s16', 'spk-ja-n5-24-naru', 16, 'prompt', 'How would you say "I became a teacher"?', '先生になりました。', 'せんせい に なりました。', NULL),
  ('spk-ja-n5-24-naru-s17', 'spk-ja-n5-24-naru', 17, 'prompt', 'How would you say "We became friends"?', '友だちになりました。', 'ともだち に なりました。', NULL),
  ('spk-ja-n5-24-naru-s18', 'spk-ja-n5-24-naru', 18, 'prompt', 'How would you say "The sushi became delicious"?', 'すしはおいしくなりました。', 'すし わ おいしく なりました。', NULL),
  ('spk-ja-n5-24-naru-s19', 'spk-ja-n5-24-naru', 19, 'prompt', 'How would you say "The school became pretty"?', '学校はきれいになりました。', 'がっこう わ きれい に なりました。', NULL),
  ('spk-ja-n5-24-naru-s20', 'spk-ja-n5-24-naru', 20, 'prompt', 'How would you say "It has become quiet here"?', 'ここはしずかになりました。', 'ここ わ しずか に なりました。', NULL),
