  ('spk-ja-n5-25-counters-s0', 'spk-ja-n5-25-counters', 0, 'explain', 'Counting. For small things, one is {ひとつ}, two is {ふたつ}, three is {みっつ}. The number goes right before the verb, after the thing. {すしをひとつたべます}.', NULL, NULL, NULL),
  ('spk-ja-n5-25-counters-s1', 'spk-ja-n5-25-counters', 1, 'prompt', 'How would you say "I eat one sushi"?', 'すしを一つ食べます。', 'すし お ひとつ たべます。', NULL),
