  ('spk-ja-n5-25-counters-s4', 'spk-ja-n5-25-counters', 4, 'prompt', 'How would you say "I want two"?', '二つほしいです。', 'ふたつ ほしい です。', NULL),
  ('spk-ja-n5-25-counters-s5', 'spk-ja-n5-25-counters', 5, 'prompt', 'How would you say "I want to eat one"?', '一つ食べたいです。', 'ひとつ たべたい です。', NULL),
  ('spk-ja-n5-25-counters-s6', 'spk-ja-n5-25-counters', 6, 'explain', 'To ask for things, say the number and {ください}. {ふたつください}, "two, please."', NULL, NULL, NULL),
