  ('spk-ja-n5-25-counters-s8', 'spk-ja-n5-25-counters', 8, 'prompt', 'How would you say "Three sushi, please"?', 'すしを三つください。', 'すし お みっつ ください。', NULL),
  ('spk-ja-n5-25-counters-s9', 'spk-ja-n5-25-counters', 9, 'explain', 'An apple is {りんご}.', NULL, NULL, NULL),
  ('spk-ja-n5-25-counters-s10', 'spk-ja-n5-25-counters', 10, 'prompt', 'How would you say "Two apples, please"?', 'りんごを二つください。', 'りんご お ふたつ ください。', NULL),
  ('spk-ja-n5-25-counters-s11', 'spk-ja-n5-25-counters', 11, 'prompt', 'How would you say "I ate three apples"?', 'りんごを三つ食べました。', 'りんご お みっつ たべました。', NULL),
  ('spk-ja-n5-25-counters-s12', 'spk-ja-n5-25-counters', 12, 'explain', '"How many" is {いくつ}.', NULL, NULL, NULL),
  ('spk-ja-n5-25-counters-s13', 'spk-ja-n5-25-counters', 13, 'prompt', 'How would you say "How many apples are there?"', 'りんごがいくつありますか。', 'りんご が いくつ あります か。', NULL),
  ('spk-ja-n5-25-counters-s14', 'spk-ja-n5-25-counters', 14, 'prompt', 'How would you say "There are three apples"?', 'りんごが三つあります。', 'りんご が みっつ あります。', NULL),
  ('spk-ja-n5-25-counters-s15', 'spk-ja-n5-25-counters', 15, 'explain', 'People are different. One person is {ひとり}. Two people is {ふたり}. From three on, it is the number and {にん}. {さんにん}.', NULL, NULL, NULL),
  ('spk-ja-n5-25-counters-s16', 'spk-ja-n5-25-counters', 16, 'prompt', 'At a restaurant, they ask how many you are. How would you say "One person"?', '一人です。', 'ひとり です。', NULL),
