  ('spk-ja-n5-25-counters-s24', 'spk-ja-n5-25-counters', 24, 'explain', 'A ticket is {きっぷ}. Flat things, like tickets, are counted with {まい}. One ticket is {いちまい}.', NULL, NULL, NULL),
