INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-26-mashouka-s0', 'spk-ja-n5-26-mashouka', 0, 'explain', 'You know {ましょう}, "let''s". Add {か} and it becomes a suggestion, "shall we?", or an offer to help, "shall I?". {たべましょうか}, "shall we eat?"', NULL, NULL, NULL),
  ('spk-ja-n5-26-mashouka-s1', 'spk-ja-n5-26-mashouka', 1, 'prompt', 'How would you say "Shall we eat?"', '食べましょうか。', 'たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s2', 'spk-ja-n5-26-mashouka', 2, 'prompt', 'How would you say "Shall we eat sushi?"', 'すしを食べましょうか。', 'すし お たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s3', 'spk-ja-n5-26-mashouka', 3, 'prompt', 'How would you say "Shall we drink tea?"', 'おちゃを飲みましょうか。', 'おちゃ お のみましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s4', 'spk-ja-n5-26-mashouka', 4, 'prompt', 'How would you say "Shall we watch TV?"', 'テレビを見ましょうか。', 'テレビ お みましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s5', 'spk-ja-n5-26-mashouka', 5, 'prompt', 'How would you say "Shall we read a book?"', '本を読みましょうか。', 'ほん お よみましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s6', 'spk-ja-n5-26-mashouka', 6, 'explain', 'To say yes to an offer, {おねがいします}. It means "please do." To say no, {だいじょうぶです}, "I''m fine."', NULL, NULL, NULL),
  ('spk-ja-n5-26-mashouka-s7', 'spk-ja-n5-26-mashouka', 7, 'prompt', 'How would you say "Yes, please"?', 'はい、おねがいします。', 'はい、おねがい します。', NULL),
  ('spk-ja-n5-26-mashouka-s8', 'spk-ja-n5-26-mashouka', 8, 'prompt', 'How would you say "No, I''m fine"?', 'いいえ、だいじょうぶです。', 'いいえ、だいじょうぶ です。', NULL),
  ('spk-ja-n5-26-mashouka-s9', 'spk-ja-n5-26-mashouka', 9, 'prompt', 'How would you say "Shall I write my name here?"', 'ここに名前を書きましょうか。', 'ここ に なまえ お かきましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s10', 'spk-ja-n5-26-mashouka', 10, 'prompt', 'How would you say "Shall we go to school?"', '学校に行きましょうか。', 'がっこう に いきましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s11', 'spk-ja-n5-26-mashouka', 11, 'prompt', 'How would you say "Shall I come to your house?"', 'あなたのうちに行きましょうか。', 'あなた の うち に いきましょう か。', 'Japanese says go, not come, when you head to their place.'),
  ('spk-ja-n5-26-mashouka-s12', 'spk-ja-n5-26-mashouka', 12, 'prompt', 'How would you say "Shall we eat together?"', 'いっしょに食べましょうか。', 'いっしょ に たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s13', 'spk-ja-n5-26-mashouka', 13, 'explain', 'With a question word, it asks for ideas. {なにをたべましょうか}, "what shall we eat?"', NULL, NULL, NULL),
  ('spk-ja-n5-26-mashouka-s14', 'spk-ja-n5-26-mashouka', 14, 'prompt', 'How would you say "What shall we eat?"', '何を食べましょうか。', 'なに お たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s15', 'spk-ja-n5-26-mashouka', 15, 'prompt', 'How would you say "Let''s eat sushi"?', 'すしを食べましょう。', 'すし お たべましょう。', NULL),
  ('spk-ja-n5-26-mashouka-s16', 'spk-ja-n5-26-mashouka', 16, 'prompt', 'How would you say "What time shall we go?"', '何時に行きましょうか。', 'なんじ に いきましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s17', 'spk-ja-n5-26-mashouka', 17, 'prompt', 'How would you say "Let''s go at seven"?', '七時に行きましょう。', 'しちじ に いきましょう。', NULL),
  ('spk-ja-n5-26-mashouka-s18', 'spk-ja-n5-26-mashouka', 18, 'prompt', 'How would you say "Where shall we eat?"', 'どこで食べましょうか。', 'どこ で たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s19', 'spk-ja-n5-26-mashouka', 19, 'prompt', 'How would you say "Let''s eat at a restaurant"?', 'レストランで食べましょう。', 'レストラン で たべましょう。', NULL),
  ('spk-ja-n5-26-mashouka-s20', 'spk-ja-n5-26-mashouka', 20, 'prompt', 'How would you say "Shall we drink tea after the meal?"', 'ごはんの後で、おちゃを飲みましょうか。', 'ごはん の あと で、おちゃ お のみましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s21', 'spk-ja-n5-26-mashouka', 21, 'prompt', 'How would you say "Shall we eat two apples?"', 'りんごを二つ食べましょうか。', 'りんご お ふたつ たべましょう か。', NULL),
  ('spk-ja-n5-26-mashouka-s22', 'spk-ja-n5-26-mashouka', 22, 'explain', '{ききます}, listen, also means ask. The person you ask takes {に}. {せんせいにききましょうか}, "shall we ask the teacher?"', NULL, NULL, NULL),
  ('spk-ja-n5-26-mashouka-s23', 'spk-ja-n5-26-mashouka', 23, 'prompt', 'How would you say "Shall we ask the teacher?"', '先生に聞きましょうか。', 'せんせい に ききましょう か。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
