SELECT 'spk-ja-n5-27-toki', 'lang-ja', ll.id, 'n5-27-toki', 27, 'ひまなとき', 'When', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-27-toki-s0', 'spk-ja-n5-27-toki', 0, 'explain', 'To say "when", as in "when I was a student", use {とき}. It means "the time". After a noun, join with {の}. {がくせいのとき}, "when I was a student."', NULL, NULL, NULL),
  ('spk-ja-n5-27-toki-s1', 'spk-ja-n5-27-toki', 1, 'prompt', 'How would you say "When I was a student, I went to Japan"?', '学生のとき、日本に行きました。', 'がくせい の とき、にほん に いきました。', NULL),
  ('spk-ja-n5-27-toki-s2', 'spk-ja-n5-27-toki', 2, 'prompt', 'How would you say "When I was a student, I went to school every day"?', '学生のとき、毎日、学校に行きました。', 'がくせい の とき、まいにち、がっこう に いきました。', NULL),
  ('spk-ja-n5-27-toki-s3', 'spk-ja-n5-27-toki', 3, 'explain', '"Free", meaning not busy, is {ひま}. It is the {しずか} kind, so it takes {な} before a noun. {ひまなとき}, "when I am free."', NULL, NULL, NULL),
  ('spk-ja-n5-27-toki-s4', 'spk-ja-n5-27-toki', 4, 'prompt', 'How would you say "When I am free, I read a book"?', 'ひまなとき、本を読みます。', 'ひまな とき、ほん お よみます。', NULL),
  ('spk-ja-n5-27-toki-s5', 'spk-ja-n5-27-toki', 5, 'prompt', 'How would you say "When I am free, I watch TV"?', 'ひまなとき、テレビを見ます。', 'ひまな とき、テレビ お みます。', NULL),
  ('spk-ja-n5-27-toki-s6', 'spk-ja-n5-27-toki', 6, 'prompt', 'How would you say "When you are free, please come to my house"?', 'ひまなとき、わたしのうちに来てください。', 'ひまな とき、わたし の うち に きて ください。', NULL),
  ('spk-ja-n5-27-toki-s7', 'spk-ja-n5-27-toki', 7, 'explain', 'With a verb, use the plain form before {とき}. {たべるとき}, "when I eat."', NULL, NULL, NULL),
  ('spk-ja-n5-27-toki-s8', 'spk-ja-n5-27-toki', 8, 'prompt', 'How would you say "When I eat, I drink tea"?', '食べるとき、おちゃを飲みます。', 'たべる とき、おちゃ お のみます。', NULL),
  ('spk-ja-n5-27-toki-s9', 'spk-ja-n5-27-toki', 9, 'prompt', 'How would you say "When I read a book, I drink tea"?', '本を読むとき、おちゃを飲みます。', 'ほん お よむ とき、おちゃ お のみます。', NULL),
  ('spk-ja-n5-27-toki-s10', 'spk-ja-n5-27-toki', 10, 'prompt', 'How would you say "When I watch TV, I eat sushi"?', 'テレビを見るとき、すしを食べます。', 'テレビ お みる とき、すし お たべます。', NULL),
  ('spk-ja-n5-27-toki-s11', 'spk-ja-n5-27-toki', 11, 'prompt', 'How would you say "When I go to school, I don''t watch TV"?', '学校に行くとき、テレビを見ません。', 'がっこう に いく とき、テレビ お みません。', NULL),
  ('spk-ja-n5-27-toki-s12', 'spk-ja-n5-27-toki', 12, 'explain', 'For something that already happened, use the plain past. {いったとき}, "when I went."', NULL, NULL, NULL),
  ('spk-ja-n5-27-toki-s13', 'spk-ja-n5-27-toki', 13, 'prompt', 'How would you say "When I went to Japan, I ate sushi"?', '日本に行ったとき、すしを食べました。', 'にほん に いった とき、すし お たべました。', NULL),
  ('spk-ja-n5-27-toki-s14', 'spk-ja-n5-27-toki', 14, 'prompt', 'How would you say "When I went to Japan, the sushi was delicious"?', '日本に行ったとき、すしはおいしかったです。', 'にほん に いった とき、すし わ おいしかった です。', NULL),
  ('spk-ja-n5-27-toki-s15', 'spk-ja-n5-27-toki', 15, 'prompt', 'How would you say "When I came to Japan, I had no friends"?', '日本に来たとき、友だちがいませんでした。', 'にほん に きた とき、ともだち が いませんでした。', NULL),
  ('spk-ja-n5-27-toki-s16', 'spk-ja-n5-27-toki', 16, 'explain', 'A describing word ending in {い} goes straight before {とき}. {ちいさいとき}, "when I was small."', NULL, NULL, NULL),
  ('spk-ja-n5-27-toki-s17', 'spk-ja-n5-27-toki', 17, 'prompt', 'How would you say "When I was small, I didn''t eat sushi"?', '小さいとき、すしを食べませんでした。', 'ちいさい とき、すし お たべませんでした。', NULL),
  ('spk-ja-n5-27-toki-s18', 'spk-ja-n5-27-toki', 18, 'prompt', 'How would you say "When I was small, I drank tea every day"?', '小さいとき、毎日、おちゃを飲みました。', 'ちいさい とき、まいにち、おちゃ お のみました。', NULL),
  ('spk-ja-n5-27-toki-s19', 'spk-ja-n5-27-toki', 19, 'prompt', 'How would you say "When it is expensive, I don''t eat"?', '高いとき、食べません。', 'たかい とき、たべません。', NULL),
  ('spk-ja-n5-27-toki-s20', 'spk-ja-n5-27-toki', 20, 'prompt', 'How would you say "What do you do when you are free?"', 'ひまなとき、何をしますか。', 'ひまな とき、なに お します か。', NULL),
  ('spk-ja-n5-27-toki-s21', 'spk-ja-n5-27-toki', 21, 'prompt', 'How would you say "When we are free, let''s read books together"?', 'ひまなとき、いっしょに本を読みましょう。', 'ひまな とき、いっしょ に ほん お よみましょう。', NULL),
  ('spk-ja-n5-27-toki-s22', 'spk-ja-n5-27-toki', 22, 'prompt', 'How would you say "What did you eat when you were a student?"', '学生のとき、何を食べましたか。', 'がくせい の とき、なに お たべました か。', NULL),
  ('spk-ja-n5-27-toki-s23', 'spk-ja-n5-27-toki', 23, 'prompt', 'How would you say "When I was a student, I ate sushi every day"?', '学生のとき、毎日、すしを食べました。', 'がくせい の とき、まいにち、すし お たべました。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-27-toki')
ON CONFLICT (session_id, index) DO NOTHING;

