-- N5 · 28 · Liking and being good at doing
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-28-noga', 'lang-ja', ll.id, 'n5-28-noga', 28, '読むのがすきです', 'Liking and being good at doing', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-28-noga-s0', 'spk-ja-n5-28-noga', 0, 'explain', 'You know {すき}, "like". To like doing something, put {の} after the plain form of the verb, and then {が}. {たべるのがすきです}, "I like eating."', NULL, NULL, NULL),
  ('spk-ja-n5-28-noga-s1', 'spk-ja-n5-28-noga', 1, 'prompt', 'How would you say "I like eating"?', '食べるのがすきです。', 'たべる の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s2', 'spk-ja-n5-28-noga', 2, 'explain', 'The plain form of {のみます} is {のむ}.', NULL, NULL, NULL),
  ('spk-ja-n5-28-noga-s3', 'spk-ja-n5-28-noga', 3, 'prompt', 'How would you say "I like drinking tea"?', 'おちゃを飲むのがすきです。', 'おちゃ お のむ の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s4', 'spk-ja-n5-28-noga', 4, 'prompt', 'How would you say "I like reading"?', '読むのがすきです。', 'よむ の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s5', 'spk-ja-n5-28-noga', 5, 'prompt', 'How would you say "I like eating sushi"?', 'すしを食べるのがすきです。', 'すし お たべる の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s6', 'spk-ja-n5-28-noga', 6, 'prompt', 'How would you say "I like reading books"?', '本を読むのがすきです。', 'ほん お よむ の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s7', 'spk-ja-n5-28-noga', 7, 'prompt', 'How would you say "I like watching TV"?', 'テレビを見るのがすきです。', 'テレビ お みる の が すき です。', NULL),
  ('spk-ja-n5-28-noga-s8', 'spk-ja-n5-28-noga', 8, 'prompt', 'How would you say "Do you like reading books?"', '本を読むのがすきですか。', 'ほん お よむ の が すき です か。', NULL),
  ('spk-ja-n5-28-noga-s9', 'spk-ja-n5-28-noga', 9, 'prompt', 'How would you say "No, I don''t like it"?', 'いいえ、すきじゃありません。', 'いいえ、すき じゃ ありません。', NULL),
  ('spk-ja-n5-28-noga-s10', 'spk-ja-n5-28-noga', 10, 'prompt', 'How would you say "I don''t like watching TV"?', 'テレビを見るのがすきじゃありません。', 'テレビ お みる の が すき じゃ ありません。', NULL),
  ('spk-ja-n5-28-noga-s11', 'spk-ja-n5-28-noga', 11, 'explain', '"Very" is {とても}. It goes before the word it strengthens.', NULL, NULL, NULL),
  ('spk-ja-n5-28-noga-s12', 'spk-ja-n5-28-noga', 12, 'prompt', 'How would you say "I like reading books very much"?', '本を読むのがとてもすきです。', 'ほん お よむ の が とても すき です。', NULL),
  ('spk-ja-n5-28-noga-s13', 'spk-ja-n5-28-noga', 13, 'explain', 'Now being good at something. "Skillful" is {じょうず}. It is the {しずか} kind. {かくのがじょうずです}, "I am good at writing."', NULL, NULL, NULL),
  ('spk-ja-n5-28-noga-s14', 'spk-ja-n5-28-noga', 14, 'prompt', 'How would you say "The teacher is good at writing"?', '先生は書くのがじょうずです。', 'せんせい わ かく の が じょうず です。', NULL),
  ('spk-ja-n5-28-noga-s15', 'spk-ja-n5-28-noga', 15, 'prompt', 'How would you say "I am good at writing"?', '書くのがじょうずです。', 'かく の が じょうず です。', 'People rarely say this about themselves. It is mostly used to praise others.'),
  ('spk-ja-n5-28-noga-s16', 'spk-ja-n5-28-noga', 16, 'prompt', 'How would you say "I am good at reading"?', '読むのがじょうずです。', 'よむ の が じょうず です。', NULL),
  ('spk-ja-n5-28-noga-s17', 'spk-ja-n5-28-noga', 17, 'prompt', 'How would you say "Are you good at writing?"', '書くのがじょうずですか。', 'かく の が じょうず です か。', NULL),
  ('spk-ja-n5-28-noga-s18', 'spk-ja-n5-28-noga', 18, 'prompt', 'How would you say "No, I am not good at it"?', 'いいえ、じょうずじゃありません。', 'いいえ、じょうず じゃ ありません。', NULL),
  ('spk-ja-n5-28-noga-s19', 'spk-ja-n5-28-noga', 19, 'explain', 'The opposite, "poor at", is {へた}.', NULL, NULL, NULL),
  ('spk-ja-n5-28-noga-s20', 'spk-ja-n5-28-noga', 20, 'prompt', 'How would you say "I am poor at writing"?', '書くのがへたです。', 'かく の が へた です。', NULL),
  ('spk-ja-n5-28-noga-s21', 'spk-ja-n5-28-noga', 21, 'prompt', 'How would you say "My friend is good at reading"?', '友だちは読むのがじょうずです。', 'ともだち わ よむ の が じょうず です。', NULL),
  ('spk-ja-n5-28-noga-s22', 'spk-ja-n5-28-noga', 22, 'prompt', 'How would you say "I like reading, so I read every day"?', '本を読むのがすきですから、毎日、読みます。', 'ほん お よむ の が すき です から、まいにち、よみます。', NULL),
  ('spk-ja-n5-28-noga-s23', 'spk-ja-n5-28-noga', 23, 'prompt', 'How would you say "I like eating, so I eat sushi every day"?', '食べるのがすきですから、毎日、すしを食べます。', 'たべる の が すき です から、まいにち、すし お たべます。', NULL),
  ('spk-ja-n5-28-noga-s24', 'spk-ja-n5-28-noga', 24, 'prompt', 'How would you say "I was poor at writing when I was small"?', '小さいとき、書くのがへたでした。', 'ちいさい とき、かく の が へた でした。', NULL),
  ('spk-ja-n5-28-noga-s25', 'spk-ja-n5-28-noga', 25, 'prompt', 'How would you say "Now I have become good at writing"?', '今、書くのがじょうずになりました。', 'いま、かく の が じょうず に なりました。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-28-noga')
ON CONFLICT (session_id, index) DO NOTHING;

