-- N5 · 29 · Probably
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-29-deshou', 'lang-ja', ll.id, 'n5-29-deshou', 29, '雨でしょう', 'Probably', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-29-deshou-s0', 'spk-ja-n5-29-deshou', 0, 'explain', 'Now guessing. Where you would say {です}, say {でしょう}, and you mean "probably". {せんせいでしょう}, "probably the teacher."', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s1', 'spk-ja-n5-29-deshou', 1, 'prompt', 'How would you say "Probably the teacher"?', '先生でしょう。', 'せんせい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s2', 'spk-ja-n5-29-deshou', 2, 'prompt', 'How would you say "Probably a student"?', '学生でしょう。', 'がくせい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s3', 'spk-ja-n5-29-deshou', 3, 'prompt', 'How would you say "It is probably delicious"?', 'おいしいでしょう。', 'おいしい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s4', 'spk-ja-n5-29-deshou', 4, 'prompt', 'How would you say "The sushi is probably delicious"?', 'すしはおいしいでしょう。', 'すし わ おいしい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s5', 'spk-ja-n5-29-deshou', 5, 'prompt', 'How would you say "It is probably expensive"?', '高いでしょう。', 'たかい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s6', 'spk-ja-n5-29-deshou', 6, 'prompt', 'How would you say "It is probably pretty"?', 'きれいでしょう。', 'きれい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s7', 'spk-ja-n5-29-deshou', 7, 'prompt', 'How would you say "Japan is probably pretty"?', '日本はきれいでしょう。', 'にほん わ きれい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s8', 'spk-ja-n5-29-deshou', 8, 'explain', 'Rain is {あめ}. Japanese says "tomorrow is probably rain".', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s9', 'spk-ja-n5-29-deshou', 9, 'prompt', 'How would you say "It will probably rain tomorrow"?', 'あしたは雨でしょう。', 'あした わ あめ でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s10', 'spk-ja-n5-29-deshou', 10, 'prompt', 'How would you say "It will probably rain today"?', '今日は雨でしょう。', 'きょう わ あめ でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s11', 'spk-ja-n5-29-deshou', 11, 'explain', 'With a verb, use the plain form. "Come" is {くる}. {くるでしょう}.', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s12', 'spk-ja-n5-29-deshou', 12, 'prompt', 'How would you say "The teacher will probably come"?', '先生は来るでしょう。', 'せんせい わ くる でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s13', 'spk-ja-n5-29-deshou', 13, 'explain', 'The plain "not" form is {こない}.', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s14', 'spk-ja-n5-29-deshou', 14, 'prompt', 'How would you say "My friend will probably not come"?', '友だちは来ないでしょう。', 'ともだち わ こない でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s15', 'spk-ja-n5-29-deshou', 15, 'prompt', 'How would you say "Tomorrow my friend will probably go to school"?', 'あした、友だちは学校に行くでしょう。', 'あした、ともだち わ がっこう に いく でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s16', 'spk-ja-n5-29-deshou', 16, 'prompt', 'How would you say "My friend will probably eat sushi"?', '友だちはすしを食べるでしょう。', 'ともだち わ すし お たべる でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s17', 'spk-ja-n5-29-deshou', 17, 'explain', '"Perhaps" is {たぶん}. It goes at the start.', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s18', 'spk-ja-n5-29-deshou', 18, 'prompt', 'How would you say "Perhaps it will rain"?', 'たぶん雨でしょう。', 'たぶん あめ でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s19', 'spk-ja-n5-29-deshou', 19, 'prompt', 'How would you say "Perhaps it is delicious"?', 'たぶんおいしいでしょう。', 'たぶん おいしい でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s20', 'spk-ja-n5-29-deshou', 20, 'prompt', 'How would you say "Perhaps the teacher will come"?', 'たぶん先生は来るでしょう。', 'たぶん せんせい わ くる でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s21', 'spk-ja-n5-29-deshou', 21, 'prompt', 'How would you say "Perhaps my friend won''t come"?', 'たぶん友だちは来ないでしょう。', 'たぶん ともだち わ こない でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s22', 'spk-ja-n5-29-deshou', 22, 'explain', 'For the past, use the plain past form. {たべたでしょう}.', NULL, NULL, NULL),
  ('spk-ja-n5-29-deshou-s23', 'spk-ja-n5-29-deshou', 23, 'prompt', 'How would you say "Perhaps my friend has already eaten"?', 'たぶん友だちはもう食べたでしょう。', 'たぶん ともだち わ もう たべた でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s24', 'spk-ja-n5-29-deshou', 24, 'prompt', 'How would you say "Perhaps it will be fine"?', 'たぶんだいじょうぶでしょう。', 'たぶん だいじょうぶ でしょう。', NULL),
  ('spk-ja-n5-29-deshou-s25', 'spk-ja-n5-29-deshou', 25, 'prompt', 'How would you say "Perhaps the school will be quiet tomorrow"?', 'たぶん、あした、学校はしずかでしょう。', 'たぶん、あした、がっこう わ しずか でしょう。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-29-deshou')
ON CONFLICT (session_id, index) DO NOTHING;

