INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-30-review-s0', 'spk-ja-n5-30-review', 0, 'explain', 'Now everything comes together, from all twenty nine sessions. Nothing here is new. It is all yours to use.', NULL, NULL, NULL),
