  ('spk-ja-n5-30-review-s3', 'spk-ja-n5-30-review', 3, 'prompt', 'How would you say "I read a book yesterday"?', 'きのう、本を読みました。', 'きのう、ほん お よみました。', NULL),
  ('spk-ja-n5-30-review-s4', 'spk-ja-n5-30-review', 4, 'prompt', 'How would you say "I want to eat sushi"?', 'すしを食べたいです。', 'すし お たべたい です。', NULL),
  ('spk-ja-n5-30-review-s5', 'spk-ja-n5-30-review', 5, 'prompt', 'How would you say "Shall we go to school?"', '学校に行きましょうか。', 'がっこう に いきましょう か。', NULL),
  ('spk-ja-n5-30-review-s6', 'spk-ja-n5-30-review', 6, 'prompt', 'How would you say "Please drink the water"?', '水を飲んでください。', 'みず お のんで ください。', NULL),
  ('spk-ja-n5-30-review-s7', 'spk-ja-n5-30-review', 7, 'prompt', 'How would you say "I want tea"?', 'おちゃがほしいです。', 'おちゃ が ほしい です。', NULL),
  ('spk-ja-n5-30-review-s8', 'spk-ja-n5-30-review', 8, 'prompt', 'How would you say "Before the meal, I drink tea"?', 'ごはんの前に、おちゃを飲みます。', 'ごはん の まえ に、おちゃ お のみます。', NULL),
  ('spk-ja-n5-30-review-s9', 'spk-ja-n5-30-review', 9, 'prompt', 'How would you say "Have you eaten yet?"', 'もう食べましたか。', 'もう たべました か。', NULL),
  ('spk-ja-n5-30-review-s10', 'spk-ja-n5-30-review', 10, 'prompt', 'How would you say "No, I haven''t eaten yet"?', 'いいえ、まだ食べていません。', 'いいえ、まだ たべて いません。', NULL),
  ('spk-ja-n5-30-review-s11', 'spk-ja-n5-30-review', 11, 'prompt', 'How would you say "The dog became big"?', 'いぬは大きくなりました。', 'いぬ わ おおきく なりました。', NULL),
  ('spk-ja-n5-30-review-s12', 'spk-ja-n5-30-review', 12, 'prompt', 'How would you say "Two apples, please"?', 'りんごを二つください。', 'りんご お ふたつ ください。', NULL),
  ('spk-ja-n5-30-review-s13', 'spk-ja-n5-30-review', 13, 'prompt', 'How would you say "I have two friends"?', '友だちが二人います。', 'ともだち が ふたり います。', NULL),
  ('spk-ja-n5-30-review-s14', 'spk-ja-n5-30-review', 14, 'prompt', 'How would you say "Shall we eat sushi?"', 'すしを食べましょうか。', 'すし お たべましょう か。', NULL),
  ('spk-ja-n5-30-review-s15', 'spk-ja-n5-30-review', 15, 'prompt', 'How would you say "When I am free, I read a book"?', 'ひまなとき、本を読みます。', 'ひまな とき、ほん お よみます。', NULL),
  ('spk-ja-n5-30-review-s16', 'spk-ja-n5-30-review', 16, 'prompt', 'How would you say "I like reading books"?', '本を読むのがすきです。', 'ほん お よむ の が すき です。', NULL),
  ('spk-ja-n5-30-review-s17', 'spk-ja-n5-30-review', 17, 'prompt', 'How would you say "Perhaps the teacher will come"?', 'たぶん先生は来るでしょう。', 'たぶん せんせい わ くる でしょう。', NULL),
  ('spk-ja-n5-30-review-s18', 'spk-ja-n5-30-review', 18, 'prompt', 'How would you say "After I eat, may I watch TV?"', '食べてから、テレビを見てもいいですか。', 'たべて から、テレビ お みても いい です か。', NULL),
  ('spk-ja-n5-30-review-s19', 'spk-ja-n5-30-review', 19, 'prompt', 'How would you say "I have been to Japan"?', '日本に行ったことがあります。', 'にほん に いった こと が あります。', NULL),
  ('spk-ja-n5-30-review-s20', 'spk-ja-n5-30-review', 20, 'prompt', 'How would you say "Japan is prettier than the school"?', '日本は学校よりきれいです。', 'にほん わ がっこう より きれい です。', NULL),
  ('spk-ja-n5-30-review-s21', 'spk-ja-n5-30-review', 21, 'prompt', 'How would you say "Sushi is delicious, so I eat it every day"?', 'すしはおいしいですから、毎日、食べます。', 'すし わ おいしい です から、まいにち、たべます。', NULL),
