-- N4 · 1 · Talking casually
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-01-plain', 'lang-ja', ll.id, 'n4-01-plain', 1, '食べる、食べない', 'Talking casually', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-01-plain-s0', 'spk-ja-n4-01-plain', 0, 'explain', 'So far you have spoken politely, with {ます} and {です}. Now the way you talk to friends and family. We call it the plain form. For a verb, the plain form is the one you find in a dictionary. {たべる}. "Eat." The polite {たべます} loses {ます} and gets {る}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s1', 'spk-ja-n4-01-plain', 1, 'prompt', 'How would you say, casually, "I eat"?', '食べる。', 'たべる。', NULL),
  ('spk-ja-n4-01-plain-s2', 'spk-ja-n4-01-plain', 2, 'prompt', 'How would you say, casually, "I eat sushi"?', 'すしを食べる。', 'すし お たべる。', NULL),
  ('spk-ja-n4-01-plain-s3', 'spk-ja-n4-01-plain', 3, 'explain', '{みます} works the same way. {みる}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s4', 'spk-ja-n4-01-plain', 4, 'prompt', 'How would you say, casually, "I watch TV"?', 'テレビを見る。', 'テレビ お みる。', NULL),
  ('spk-ja-n4-01-plain-s5', 'spk-ja-n4-01-plain', 5, 'explain', 'Other verbs change their last sound instead. The {み} in {よみます} turns into {む}. {よむ}. And {のみます} becomes {のむ}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s6', 'spk-ja-n4-01-plain', 6, 'prompt', 'How would you say, casually, "I read a book"?', '本を読む。', 'ほん お よむ。', NULL),
  ('spk-ja-n4-01-plain-s7', 'spk-ja-n4-01-plain', 7, 'prompt', 'How would you say, casually, "I drink tea"?', 'おちゃを飲む。', 'おちゃ お のむ。', NULL),
  ('spk-ja-n4-01-plain-s8', 'spk-ja-n4-01-plain', 8, 'explain', '{かえります} ends in {り}. The {り} turns into {る}. {かえる}. In {いきます}, the {き} turns into {く}. {いく}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s9', 'spk-ja-n4-01-plain', 9, 'prompt', 'How would you say, casually, "I go home"?', 'うちに帰る。', 'うち に かえる。', NULL),
  ('spk-ja-n4-01-plain-s10', 'spk-ja-n4-01-plain', 10, 'prompt', 'How would you say, casually, "I go to school"?', '学校に行く。', 'がっこう に いく。', NULL),
  ('spk-ja-n4-01-plain-s11', 'spk-ja-n4-01-plain', 11, 'explain', '{かきます} becomes {かく}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s12', 'spk-ja-n4-01-plain', 12, 'prompt', 'How would you say, casually, "I write my name"?', '名前を書く。', 'なまえ お かく。', NULL),
  ('spk-ja-n4-01-plain-s13', 'spk-ja-n4-01-plain', 13, 'explain', '{きます}, to come, is special. It becomes {くる}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s14', 'spk-ja-n4-01-plain', 14, 'prompt', 'How would you say, casually, "I come to school"?', '学校に来る。', 'がっこう に くる。', NULL),
  ('spk-ja-n4-01-plain-s15', 'spk-ja-n4-01-plain', 15, 'explain', 'For "not", you already know the {ない} form from {たべないでください}. On its own, it is the plain "not". {たべない}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s16', 'spk-ja-n4-01-plain', 16, 'prompt', 'How would you say, casually, "I don''t eat"?', '食べない。', 'たべない。', NULL),
  ('spk-ja-n4-01-plain-s17', 'spk-ja-n4-01-plain', 17, 'prompt', 'How would you say, casually, "I don''t eat sushi"?', 'すしを食べない。', 'すし お たべない。', NULL),
  ('spk-ja-n4-01-plain-s18', 'spk-ja-n4-01-plain', 18, 'prompt', 'How would you say, casually, "I don''t go to school"?', '学校に行かない。', 'がっこう に いかない。', NULL),
  ('spk-ja-n4-01-plain-s19', 'spk-ja-n4-01-plain', 19, 'prompt', 'How would you say, casually, "I don''t read books"?', '本を読まない。', 'ほん お よまない。', NULL),
  ('spk-ja-n4-01-plain-s20', 'spk-ja-n4-01-plain', 20, 'prompt', 'How would you say, casually, "I don''t come"?', '来ない。', 'こない。', NULL),
  ('spk-ja-n4-01-plain-s21', 'spk-ja-n4-01-plain', 21, 'explain', 'To ask a friend a question, drop {か} and let your voice go up. {たべる}, with a rising voice, means "do you eat?"', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s22', 'spk-ja-n4-01-plain', 22, 'prompt', 'How would you say, casually, "Do you eat sushi?"', 'すしを食べる？', 'すし お たべる？', NULL),
  ('spk-ja-n4-01-plain-s23', 'spk-ja-n4-01-plain', 23, 'prompt', 'How would you say, casually, "Do you go to school?"', '学校に行く？', 'がっこう に いく？', NULL),
  ('spk-ja-n4-01-plain-s24', 'spk-ja-n4-01-plain', 24, 'explain', 'The plain form of {です} is {だ}. {これはほんだ}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s25', 'spk-ja-n4-01-plain', 25, 'prompt', 'How would you say, casually, "This is a book"?', 'これは本だ。', 'これ わ ほん だ。', NULL),
  ('spk-ja-n4-01-plain-s26', 'spk-ja-n4-01-plain', 26, 'prompt', 'How would you say, casually, "That is water"?', 'それは水だ。', 'それ わ みず だ。', NULL),
  ('spk-ja-n4-01-plain-s27', 'spk-ja-n4-01-plain', 27, 'prompt', 'How would you say, casually, "I am a student"?', 'わたしは学生だ。', 'わたし わ がくせい だ。', 'Among friends people often drop the final da. With it, a statement can sound blunt.'),
  ('spk-ja-n4-01-plain-s28', 'spk-ja-n4-01-plain', 28, 'explain', 'In a question you leave {だ} out. Just {これはほん}, with a rising voice.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s29', 'spk-ja-n4-01-plain', 29, 'prompt', 'How would you say, casually, "Is this a book?"', 'これは本？', 'これ わ ほん？', NULL),
  ('spk-ja-n4-01-plain-s30', 'spk-ja-n4-01-plain', 30, 'explain', 'For "is not", {じゃありません} becomes {じゃない}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s31', 'spk-ja-n4-01-plain', 31, 'prompt', 'How would you say, casually, "I am not a student"?', 'わたしは学生じゃない。', 'わたし わ がくせい じゃ ない。', NULL),
  ('spk-ja-n4-01-plain-s32', 'spk-ja-n4-01-plain', 32, 'explain', 'The {から} you know as "because" joins straight onto a plain form. No {です}. {たかいから}. After {しずか}, you need {だ}. {しずかだから}.', NULL, NULL, NULL),
  ('spk-ja-n4-01-plain-s33', 'spk-ja-n4-01-plain', 33, 'prompt', 'How would you say, casually, "It is expensive, so I don''t eat"?', '高いから、食べない。', 'たかい から、たべない。', NULL),
  ('spk-ja-n4-01-plain-s34', 'spk-ja-n4-01-plain', 34, 'prompt', 'How would you say, casually, "It is quiet, so I read a book here"?', 'しずかだから、ここで本を読む。', 'しずか だ から、ここ で ほん お よむ。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-01-plain')
ON CONFLICT (session_id, index) DO NOTHING;

