SELECT 'crq-spk-ja-n4-01-plain', 'lang-ja', 'speak_sessions', 'spk-ja-n4-01-plain', 'create', '{"code":"n4-01-plain","level":"N4","number":1}'::jsonb, 'ai', 2001, 'pending'
