-- N4 · 2 · Casual past
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-02-plain-past', 'lang-ja', ll.id, 'n4-02-plain-past', 2, '食べた、食べなかった', 'Casual past', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-02-plain-past-s0', 'spk-ja-n4-02-plain-past', 0, 'explain', 'The casual past is a form you already know, from {たべたことがあります}. {たべた}. "Ate."', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s1', 'spk-ja-n4-02-plain-past', 1, 'prompt', 'How would you say, casually, "I ate"?', '食べた。', 'たべた。', NULL),
  ('spk-ja-n4-02-plain-past-s2', 'spk-ja-n4-02-plain-past', 2, 'prompt', 'How would you say, casually, "I ate sushi"?', 'すしを食べた。', 'すし お たべた。', NULL),
  ('spk-ja-n4-02-plain-past-s3', 'spk-ja-n4-02-plain-past', 3, 'prompt', 'How would you say, casually, "I watched TV"?', 'テレビを見た。', 'テレビ お みた。', NULL),
  ('spk-ja-n4-02-plain-past-s4', 'spk-ja-n4-02-plain-past', 4, 'explain', 'The same {た} form as before. {よんだ}, {のんだ}, {いった}, {かえった}, {かいた}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s5', 'spk-ja-n4-02-plain-past', 5, 'prompt', 'How would you say, casually, "I read a book"?', '本を読んだ。', 'ほん お よんだ。', NULL),
  ('spk-ja-n4-02-plain-past-s6', 'spk-ja-n4-02-plain-past', 6, 'prompt', 'How would you say, casually, "I drank tea"?', 'おちゃを飲んだ。', 'おちゃ お のんだ。', NULL),
  ('spk-ja-n4-02-plain-past-s7', 'spk-ja-n4-02-plain-past', 7, 'prompt', 'How would you say, casually, "I went to school"?', '学校に行った。', 'がっこう に いった。', NULL),
  ('spk-ja-n4-02-plain-past-s8', 'spk-ja-n4-02-plain-past', 8, 'prompt', 'How would you say, casually, "I went home"?', 'うちに帰った。', 'うち に かえった。', NULL),
  ('spk-ja-n4-02-plain-past-s9', 'spk-ja-n4-02-plain-past', 9, 'prompt', 'How would you say, casually, "I wrote my name"?', '名前を書いた。', 'なまえ お かいた。', NULL),
  ('spk-ja-n4-02-plain-past-s10', 'spk-ja-n4-02-plain-past', 10, 'explain', '{きます} gives {きた}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s11', 'spk-ja-n4-02-plain-past', 11, 'prompt', 'How would you say, casually, "I came"?', '来た。', 'きた。', NULL),
  ('spk-ja-n4-02-plain-past-s12', 'spk-ja-n4-02-plain-past', 12, 'explain', 'For the casual "did not", take the plain "not", {たべない}, drop the final {い}, and add {かった}. {たべなかった}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s13', 'spk-ja-n4-02-plain-past', 13, 'prompt', 'How would you say, casually, "I didn''t eat"?', '食べなかった。', 'たべなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s14', 'spk-ja-n4-02-plain-past', 14, 'prompt', 'How would you say, casually, "I didn''t eat sushi"?', 'すしを食べなかった。', 'すし お たべなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s15', 'spk-ja-n4-02-plain-past', 15, 'prompt', 'How would you say, casually, "I didn''t go to school"?', '学校に行かなかった。', 'がっこう に いかなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s16', 'spk-ja-n4-02-plain-past', 16, 'prompt', 'How would you say, casually, "I didn''t read a book"?', '本を読まなかった。', 'ほん お よまなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s17', 'spk-ja-n4-02-plain-past', 17, 'prompt', 'How would you say, casually, "I didn''t come"?', '来なかった。', 'こなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s18', 'spk-ja-n4-02-plain-past', 18, 'explain', 'To ask a friend, again drop {か} and raise your voice. {たべた}, rising, is "did you eat?"', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s19', 'spk-ja-n4-02-plain-past', 19, 'prompt', 'How would you say, casually, "Did you eat sushi?"', 'すしを食べた？', 'すし お たべた？', NULL),
  ('spk-ja-n4-02-plain-past-s20', 'spk-ja-n4-02-plain-past', 20, 'prompt', 'How would you say, casually, "Did you go to school yesterday?"', 'きのう、学校に行った？', 'きのう、がっこう に いった？', NULL),
  ('spk-ja-n4-02-plain-past-s21', 'spk-ja-n4-02-plain-past', 21, 'explain', 'Casual answers. "Yes" is {うん}. "No" is {ううん}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s22', 'spk-ja-n4-02-plain-past', 22, 'prompt', 'How would you say, casually, "Yes, I ate"?', 'うん、食べた。', 'うん、たべた。', NULL),
  ('spk-ja-n4-02-plain-past-s23', 'spk-ja-n4-02-plain-past', 23, 'prompt', 'How would you say, casually, "No, I didn''t eat"?', 'ううん、食べなかった。', 'ううん、たべなかった。', NULL),
  ('spk-ja-n4-02-plain-past-s24', 'spk-ja-n4-02-plain-past', 24, 'explain', 'The past of {だ} is {だった}. And "was not" is {じゃなかった}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s25', 'spk-ja-n4-02-plain-past', 25, 'prompt', 'How would you say, casually, "It was a book"?', '本だった。', 'ほん だった。', NULL),
  ('spk-ja-n4-02-plain-past-s26', 'spk-ja-n4-02-plain-past', 26, 'prompt', 'How would you say, casually, "It was not a book"?', '本じゃなかった。', 'ほん じゃ なかった。', NULL),
  ('spk-ja-n4-02-plain-past-s27', 'spk-ja-n4-02-plain-past', 27, 'explain', 'You already know {い} words in the past. {たかかった}. {おいしかった}. Just leave off {です}.', NULL, NULL, NULL),
  ('spk-ja-n4-02-plain-past-s28', 'spk-ja-n4-02-plain-past', 28, 'prompt', 'How would you say, casually, "It was expensive"?', '高かった。', 'たかかった。', NULL),
  ('spk-ja-n4-02-plain-past-s29', 'spk-ja-n4-02-plain-past', 29, 'prompt', 'How would you say, casually, "I ate sushi yesterday. It was delicious."?', 'きのう、すしを食べた。おいしかった。', 'きのう、すし お たべた。おいしかった。', NULL),
  ('spk-ja-n4-02-plain-past-s30', 'spk-ja-n4-02-plain-past', 30, 'prompt', 'How would you say, casually, "It was expensive, so I didn''t eat"?', '高かったから、食べなかった。', 'たかかった から、たべなかった。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
