INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-03-to-omoimasu-s0', 'spk-ja-n4-03-to-omoimasu', 0, 'explain', 'To say what you think, put a plain form first, then {と}, then {おもいます}. {と} works like the word "that" in "I think that". Because the thought sits inside, it uses the plain form you just learned.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s1', 'spk-ja-n4-03-to-omoimasu', 1, 'explain', 'You know {せんせい}, the teacher. {せんせいは たべると おもいます}. "I think the teacher will eat."', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s2', 'spk-ja-n4-03-to-omoimasu', 2, 'prompt', 'How would you say "I think the teacher will eat"?', '先生は食べると思います。', 'せんせい わ たべる と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s3', 'spk-ja-n4-03-to-omoimasu', 3, 'prompt', 'How would you say "I think the teacher will eat sushi"?', '先生はすしを食べると思います。', 'せんせい わ すし お たべる と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s4', 'spk-ja-n4-03-to-omoimasu', 4, 'prompt', 'How would you say "I think the teacher will go to school"?', '先生は学校に行くと思います。', 'せんせい わ がっこう に いく と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s5', 'spk-ja-n4-03-to-omoimasu', 5, 'prompt', 'How would you say "I think the teacher will come"?', '先生は来ると思います。', 'せんせい わ くる と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s6', 'spk-ja-n4-03-to-omoimasu', 6, 'explain', 'For "will not", use the plain {ない} form. {こないと おもいます}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s7', 'spk-ja-n4-03-to-omoimasu', 7, 'prompt', 'How would you say "I think the teacher won''t come"?', '先生は来ないと思います。', 'せんせい わ こない と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s8', 'spk-ja-n4-03-to-omoimasu', 8, 'prompt', 'How would you say "I think the teacher won''t go to school"?', '先生は学校に行かないと思います。', 'せんせい わ がっこう に いかない と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s9', 'spk-ja-n4-03-to-omoimasu', 9, 'explain', 'When the thought is "it is something", the plain {だ} stays. {ほんだと おもいます}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s10', 'spk-ja-n4-03-to-omoimasu', 10, 'prompt', 'How would you say "I think this is the teacher''s book"?', 'これは先生の本だと思います。', 'これ わ せんせい の ほん だ と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s11', 'spk-ja-n4-03-to-omoimasu', 11, 'prompt', 'How would you say "I think that is water"?', 'それは水だと思います。', 'それ わ みず だ と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s12', 'spk-ja-n4-03-to-omoimasu', 12, 'prompt', 'How would you say "I think that is not water"?', 'それは水じゃないと思います。', 'それ わ みず じゃ ない と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s13', 'spk-ja-n4-03-to-omoimasu', 13, 'explain', 'The {い} kind of describing word needs no {だ}. {おいしいと おもいます}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s14', 'spk-ja-n4-03-to-omoimasu', 14, 'prompt', 'How would you say "I think the sushi is delicious"?', 'すしはおいしいと思います。', 'すし わ おいしい と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s15', 'spk-ja-n4-03-to-omoimasu', 15, 'prompt', 'How would you say "I think the restaurant is expensive"?', 'レストランは高いと思います。', 'レストラン わ たかい と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s16', 'spk-ja-n4-03-to-omoimasu', 16, 'explain', 'The {しずか} kind keeps its {だ}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s17', 'spk-ja-n4-03-to-omoimasu', 17, 'prompt', 'How would you say "I think the restaurant is quiet"?', 'レストランはしずかだと思います。', 'レストラン わ しずか だ と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s18', 'spk-ja-n4-03-to-omoimasu', 18, 'explain', 'The past works too. Use the plain past before {と}. {たべたと おもいます}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s19', 'spk-ja-n4-03-to-omoimasu', 19, 'prompt', 'How would you say "I think the teacher ate sushi yesterday"?', '先生はきのう、すしを食べたと思います。', 'せんせい わ きのう、すし お たべた と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s20', 'spk-ja-n4-03-to-omoimasu', 20, 'prompt', 'How would you say "I think the teacher went to Japan"?', '先生は日本に行ったと思います。', 'せんせい わ にほん に いった と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s21', 'spk-ja-n4-03-to-omoimasu', 21, 'prompt', 'How would you say "I think the sushi was delicious"?', 'すしはおいしかったと思います。', 'すし わ おいしかった と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s22', 'spk-ja-n4-03-to-omoimasu', 22, 'explain', 'To ask for someone''s opinion, add {か}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s23', 'spk-ja-n4-03-to-omoimasu', 23, 'prompt', 'How would you say "Do you think the teacher will come?"', '先生は来ると思いますか。', 'せんせい わ くる と おもいます か。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s24', 'spk-ja-n4-03-to-omoimasu', 24, 'explain', '{そう} is the "so" in "I think so". {そう おもいます}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s25', 'spk-ja-n4-03-to-omoimasu', 25, 'prompt', 'How would you say "Yes, I think so"?', 'はい、そう思います。', 'はい、そう おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s26', 'spk-ja-n4-03-to-omoimasu', 26, 'prompt', 'How would you say "No, I don''t think so"?', 'いいえ、そう思いません。', 'いいえ、そう おもいません。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s27', 'spk-ja-n4-03-to-omoimasu', 27, 'prompt', 'How would you say "I think so too"?', 'わたしもそう思います。', 'わたし も そう おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s28', 'spk-ja-n4-03-to-omoimasu', 28, 'explain', '{います} has a plain form too. {いる}. So {よんでいます} becomes {よんでいる}.', NULL, NULL, NULL),
  ('spk-ja-n4-03-to-omoimasu-s29', 'spk-ja-n4-03-to-omoimasu', 29, 'prompt', 'How would you say "I think the teacher is reading a book at home now"?', '今、先生はうちで本を読んでいると思います。', 'いま、せんせい わ うち で ほん お よんで いる と おもいます。', NULL),
  ('spk-ja-n4-03-to-omoimasu-s30', 'spk-ja-n4-03-to-omoimasu', 30, 'prompt', 'How would you say "I think it is delicious, so I will eat"?', 'おいしいと思いますから、食べます。', 'おいしい と おもいます から、たべます。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-03-to-omoimasu')
ON CONFLICT (session_id, index) DO NOTHING;

