INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-04-koto-s0', 'spk-ja-n4-04-koto', 0, 'explain', 'To say you can do something, take the plain dictionary form and add {ことができます}. It means "I am able to do the act of". {たべることができます}. "I can eat."', NULL, NULL, NULL),
  ('spk-ja-n4-04-koto-s1', 'spk-ja-n4-04-koto', 1, 'prompt', 'How would you say "I can eat"?', '食べることができます。', 'たべる こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s2', 'spk-ja-n4-04-koto', 2, 'prompt', 'How would you say "I can eat sushi"?', 'すしを食べることができます。', 'すし お たべる こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s3', 'spk-ja-n4-04-koto', 3, 'prompt', 'How would you say "I can read a book"?', '本を読むことができます。', 'ほん お よむ こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s4', 'spk-ja-n4-04-koto', 4, 'prompt', 'How would you say "I can go to school"?', '学校に行くことができます。', 'がっこう に いく こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s5', 'spk-ja-n4-04-koto', 5, 'prompt', 'How would you say "I can come tomorrow"?', 'あした、来ることができます。', 'あした、くる こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s6', 'spk-ja-n4-04-koto', 6, 'explain', 'For "cannot", change the end to {ことができません}.', NULL, NULL, NULL),
  ('spk-ja-n4-04-koto-s7', 'spk-ja-n4-04-koto', 7, 'prompt', 'How would you say "I cannot eat"?', '食べることができません。', 'たべる こと が できません。', NULL),
  ('spk-ja-n4-04-koto-s8', 'spk-ja-n4-04-koto', 8, 'prompt', 'How would you say "I cannot drink tea"?', 'おちゃを飲むことができません。', 'おちゃ お のむ こと が できません。', NULL),
  ('spk-ja-n4-04-koto-s9', 'spk-ja-n4-04-koto', 9, 'prompt', 'How would you say "I cannot read a book here"?', 'ここで本を読むことができません。', 'ここ で ほん お よむ こと が できません。', NULL),
  ('spk-ja-n4-04-koto-s10', 'spk-ja-n4-04-koto', 10, 'prompt', 'How would you say "Can you eat sushi?"', 'すしを食べることができますか。', 'すし お たべる こと が できます か。', NULL),
  ('spk-ja-n4-04-koto-s11', 'spk-ja-n4-04-koto', 11, 'explain', 'On its own, {できます} means "I can". {できません}, "I can''t".', NULL, NULL, NULL),
  ('spk-ja-n4-04-koto-s12', 'spk-ja-n4-04-koto', 12, 'prompt', 'How would you say "Yes, I can"?', 'はい、できます。', 'はい、できます。', NULL),
  ('spk-ja-n4-04-koto-s13', 'spk-ja-n4-04-koto', 13, 'prompt', 'How would you say "No, I can''t"?', 'いいえ、できません。', 'いいえ、できません。', NULL),
  ('spk-ja-n4-04-koto-s14', 'spk-ja-n4-04-koto', 14, 'explain', '"Speak" is {はなす}. "Japanese", the language, is {にほんご}.', NULL, NULL, NULL),
  ('spk-ja-n4-04-koto-s15', 'spk-ja-n4-04-koto', 15, 'prompt', 'How would you say "I can speak Japanese"?', '日本語を話すことができます。', 'にほんご お はなす こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s16', 'spk-ja-n4-04-koto', 16, 'prompt', 'How would you say "Can you speak Japanese?"', '日本語を話すことができますか。', 'にほんご お はなす こと が できます か。', NULL),
  ('spk-ja-n4-04-koto-s17', 'spk-ja-n4-04-koto', 17, 'prompt', 'How would you say "The teacher can speak Japanese"?', '先生は日本語を話すことができます。', 'せんせい わ にほんご お はなす こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s18', 'spk-ja-n4-04-koto', 18, 'explain', 'The language you do something in takes {で}. {にほんごで}, "in Japanese".', NULL, NULL, NULL),
  ('spk-ja-n4-04-koto-s19', 'spk-ja-n4-04-koto', 19, 'prompt', 'How would you say "I can read a book in Japanese"?', '日本語で本を読むことができます。', 'にほんご で ほん お よむ こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s20', 'spk-ja-n4-04-koto', 20, 'prompt', 'How would you say "I can write my name in Japanese"?', '日本語で名前を書くことができます。', 'にほんご で なまえ お かく こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s21', 'spk-ja-n4-04-koto', 21, 'prompt', 'How would you say "I can watch TV here"?', 'ここでテレビを見ることができます。', 'ここ で テレビ お みる こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s22', 'spk-ja-n4-04-koto', 22, 'prompt', 'How would you say "I cannot eat here"?', 'ここで食べることができません。', 'ここ で たべる こと が できません。', NULL),
  ('spk-ja-n4-04-koto-s23', 'spk-ja-n4-04-koto', 23, 'prompt', 'How would you say "Can you come to school at eight?"', '八時に学校に来ることができますか。', 'はちじ に がっこう に くる こと が できます か。', NULL),
  ('spk-ja-n4-04-koto-s24', 'spk-ja-n4-04-koto', 24, 'prompt', 'How would you say "It is quiet, so I can read a book here"?', 'しずかですから、ここで本を読むことができます。', 'しずか です から、ここ で ほん お よむ こと が できます。', NULL),
  ('spk-ja-n4-04-koto-s25', 'spk-ja-n4-04-koto', 25, 'prompt', 'How would you say "I am reading a book now, so I cannot go"?', '今、本を読んでいますから、行くことができません。', 'いま、ほん お よんで います から、いく こと が できません。', NULL),
  ('spk-ja-n4-04-koto-s26', 'spk-ja-n4-04-koto', 26, 'prompt', 'How would you say "I can speak Japanese, so I want to go to Japan"?', '日本語を話すことができますから、日本に行きたいです。', 'にほんご お はなす こと が できます から、にほん に いきたい です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-04-koto')
