INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-05-tsumori-s0', 'spk-ja-n4-05-tsumori', 0, 'explain', 'To say what you intend to do, take the plain dictionary form and add {つもりです}. {つもり} means "intention". {いくつもりです}. "I intend to go."', NULL, NULL, NULL),
  ('spk-ja-n4-05-tsumori-s1', 'spk-ja-n4-05-tsumori', 1, 'prompt', 'How would you say "I intend to eat"?', '食べるつもりです。', 'たべる つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s2', 'spk-ja-n4-05-tsumori', 2, 'prompt', 'How would you say "I intend to eat sushi"?', 'すしを食べるつもりです。', 'すし お たべる つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s3', 'spk-ja-n4-05-tsumori', 3, 'prompt', 'How would you say "I intend to go to Japan"?', '日本に行くつもりです。', 'にほん に いく つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s4', 'spk-ja-n4-05-tsumori', 4, 'prompt', 'How would you say "I intend to go to Japan tomorrow"?', 'あした、日本に行くつもりです。', 'あした、にほん に いく つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s5', 'spk-ja-n4-05-tsumori', 5, 'explain', 'For "I intend not to", use the plain {ない} form. {いかない つもりです}.', NULL, NULL, NULL),
  ('spk-ja-n4-05-tsumori-s6', 'spk-ja-n4-05-tsumori', 6, 'prompt', 'How would you say "I intend not to eat"?', '食べないつもりです。', 'たべない つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s7', 'spk-ja-n4-05-tsumori', 7, 'prompt', 'How would you say "I intend not to go to school tomorrow"?', 'あした、学校に行かないつもりです。', 'あした、がっこう に いかない つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s8', 'spk-ja-n4-05-tsumori', 8, 'prompt', 'How would you say "Do you intend to go to Japan?"', '日本に行くつもりですか。', 'にほん に いく つもり です か。', NULL),
  ('spk-ja-n4-05-tsumori-s9', 'spk-ja-n4-05-tsumori', 9, 'explain', 'The plain form of {します} is {する}. "Do." {なにを するつもりですか}, "what do you intend to do?"', NULL, NULL, NULL),
  ('spk-ja-n4-05-tsumori-s10', 'spk-ja-n4-05-tsumori', 10, 'prompt', 'How would you say "What do you intend to do tomorrow?"', 'あした、何をするつもりですか。', 'あした、なに お する つもり です か。', NULL),
  ('spk-ja-n4-05-tsumori-s11', 'spk-ja-n4-05-tsumori', 11, 'prompt', 'How would you say "What do you intend to do in Japan?"', '日本で何をするつもりですか。', 'にほん で なに お する つもり です か。', NULL),
  ('spk-ja-n4-05-tsumori-s12', 'spk-ja-n4-05-tsumori', 12, 'prompt', 'How would you say "I intend to read books in Japan"?', '日本で本を読むつもりです。', 'にほん で ほん お よむ つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s13', 'spk-ja-n4-05-tsumori', 13, 'prompt', 'How would you say "I intend to go to a friend''s home"?', '友だちのうちに行くつもりです。', 'ともだち の うち に いく つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s14', 'spk-ja-n4-05-tsumori', 14, 'explain', '"When" is {いつ}. It sits where the answer would sit.', NULL, NULL, NULL),
  ('spk-ja-n4-05-tsumori-s15', 'spk-ja-n4-05-tsumori', 15, 'prompt', 'How would you say "When do you intend to go to Japan?"', 'いつ日本に行くつもりですか。', 'いつ にほん に いく つもり です か。', NULL),
  ('spk-ja-n4-05-tsumori-s16', 'spk-ja-n4-05-tsumori', 16, 'explain', '"Next year" is {らいねん}.', NULL, NULL, NULL),
  ('spk-ja-n4-05-tsumori-s17', 'spk-ja-n4-05-tsumori', 17, 'prompt', 'How would you say "I intend to go to Japan next year"?', '来年、日本に行くつもりです。', 'らいねん、にほん に いく つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s18', 'spk-ja-n4-05-tsumori', 18, 'prompt', 'How would you say "I intend to speak Japanese every day"?', '毎日、日本語を話すつもりです。', 'まいにち、にほんご お はなす つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s19', 'spk-ja-n4-05-tsumori', 19, 'prompt', 'How would you say "On Sunday, I intend to read a book at home"?', '日曜日は、うちで本を読むつもりです。', 'にちようび わ、うち で ほん お よむ つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s20', 'spk-ja-n4-05-tsumori', 20, 'prompt', 'How would you say "Do you intend to come to my home on Sunday?"', '日曜日、わたしのうちに来るつもりですか。', 'にちようび、わたし の うち に くる つもり です か。', 'Asking someone straight out what they intend can sound pushy to a superior. With friends it is fine.'),
  ('spk-ja-n4-05-tsumori-s21', 'spk-ja-n4-05-tsumori', 21, 'prompt', 'How would you say "After I eat, I intend to go home"?', '食べてから、うちに帰るつもりです。', 'たべて から、うち に かえる つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s22', 'spk-ja-n4-05-tsumori', 22, 'prompt', 'How would you say "It is expensive, so I intend not to eat"?', '高いですから、食べないつもりです。', 'たかい です から、たべない つもり です。', NULL),
  ('spk-ja-n4-05-tsumori-s23', 'spk-ja-n4-05-tsumori', 23, 'prompt', 'How would you say "I have never been to Japan, so I intend to go next year"?', '日本に行ったことがありませんから、来年、行くつもりです。', 'にほん に いった こと が ありません から、らいねん、いく つもり です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-05-tsumori')
ON CONFLICT (session_id, index) DO NOTHING;

