-- N4 · 6 · I must
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-06-nakereba', 'lang-ja', ll.id, 'n4-06-nakereba', 6, '行かなければなりません', 'I must', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-06-nakereba-s0', 'spk-ja-n4-06-nakereba', 0, 'explain', 'To say you must do something, take the plain {ない} form, drop the final {い}, and add {ければなりません}. {たべない} becomes {たべなければなりません}. Literally, "if I don''t eat, it won''t do". "I must eat."', NULL, NULL, NULL),
  ('spk-ja-n4-06-nakereba-s1', 'spk-ja-n4-06-nakereba', 1, 'prompt', 'How would you say "I must eat"?', '食べなければなりません。', 'たべなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s2', 'spk-ja-n4-06-nakereba', 2, 'prompt', 'How would you say "I must go to school"?', '学校に行かなければなりません。', 'がっこう に いかなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s3', 'spk-ja-n4-06-nakereba', 3, 'prompt', 'How would you say "I must read this book"?', 'この本を読まなければなりません。', 'この ほん お よまなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s4', 'spk-ja-n4-06-nakereba', 4, 'prompt', 'How would you say "I must go home"?', 'うちに帰らなければなりません。', 'うち に かえらなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s5', 'spk-ja-n4-06-nakereba', 5, 'prompt', 'How would you say "I must write my name"?', '名前を書かなければなりません。', 'なまえ お かかなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s6', 'spk-ja-n4-06-nakereba', 6, 'prompt', 'How would you say "I must come"?', '来なければなりません。', 'こなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s7', 'spk-ja-n4-06-nakereba', 7, 'prompt', 'How would you say "I must go to school at eight"?', '八時に学校に行かなければなりません。', 'はちじ に がっこう に いかなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s8', 'spk-ja-n4-06-nakereba', 8, 'prompt', 'How would you say "I must read books every day"?', '毎日、本を読まなければなりません。', 'まいにち、ほん お よまなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s9', 'spk-ja-n4-06-nakereba', 9, 'prompt', 'How would you say "I must go home today"?', '今日はうちに帰らなければなりません。', 'きょう わ うち に かえらなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s10', 'spk-ja-n4-06-nakereba', 10, 'explain', 'To ask, add {か}.', NULL, NULL, NULL),
  ('spk-ja-n4-06-nakereba-s11', 'spk-ja-n4-06-nakereba', 11, 'prompt', 'How would you say "Must I go home now?"', '今、帰らなければなりませんか。', 'いま、かえらなければ なりません か。', NULL),
  ('spk-ja-n4-06-nakereba-s12', 'spk-ja-n4-06-nakereba', 12, 'prompt', 'How would you say "Yes, you must go home"?', 'はい、帰らなければなりません。', 'はい、かえらなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s13', 'spk-ja-n4-06-nakereba', 13, 'explain', '{おきます} and {ねます} work like {たべます}. {おきない}, {おきなければなりません}.', NULL, NULL, NULL),
  ('spk-ja-n4-06-nakereba-s14', 'spk-ja-n4-06-nakereba', 14, 'prompt', 'How would you say "I must get up at seven tomorrow"?', 'あした、七時におきなければなりません。', 'あした、しちじ に おきなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s15', 'spk-ja-n4-06-nakereba', 15, 'prompt', 'How would you say "I must sleep at ten"?', '十時にねなければなりません。', 'じゅうじ に ねなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s16', 'spk-ja-n4-06-nakereba', 16, 'explain', '{はなす} gives {はなさない}. {はなさなければなりません}.', NULL, NULL, NULL),
  ('spk-ja-n4-06-nakereba-s17', 'spk-ja-n4-06-nakereba', 17, 'prompt', 'How would you say "I must speak Japanese"?', '日本語を話さなければなりません。', 'にほんご お はなさなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s18', 'spk-ja-n4-06-nakereba', 18, 'prompt', 'How would you say "I must speak Japanese here"?', 'ここで日本語を話さなければなりません。', 'ここ で にほんご お はなさなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s19', 'spk-ja-n4-06-nakereba', 19, 'prompt', 'How would you say "What time must I go to school?"', '何時に学校に行かなければなりませんか。', 'なんじ に がっこう に いかなければ なりません か。', NULL),
  ('spk-ja-n4-06-nakereba-s20', 'spk-ja-n4-06-nakereba', 20, 'prompt', 'How would you say "Must I write my name here?"', 'ここに名前を書かなければなりませんか。', 'ここ に なまえ お かかなければ なりません か。', NULL),
  ('spk-ja-n4-06-nakereba-s21', 'spk-ja-n4-06-nakereba', 21, 'prompt', 'How would you say "After I eat, I must read a book"?', '食べてから、本を読まなければなりません。', 'たべて から、ほん お よまなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s22', 'spk-ja-n4-06-nakereba', 22, 'prompt', 'How would you say "I intend to go to Japan, so I must speak Japanese"?', '日本に行くつもりですから、日本語を話さなければなりません。', 'にほん に いく つもり です から、にほんご お はなさなければ なりません。', NULL),
  ('spk-ja-n4-06-nakereba-s23', 'spk-ja-n4-06-nakereba', 23, 'prompt', 'How would you say "I must go to a friend''s home today, so I cannot go to school"?', '今日は友だちのうちに行かなければなりませんから、学校に行くことができません。', 'きょう わ ともだち の うち に いかなければ なりません から、がっこう に いく こと が できません。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-06-nakereba')
ON CONFLICT (session_id, index) DO NOTHING;

