SELECT 'crq-spk-ja-n4-06-nakereba', 'lang-ja', 'speak_sessions', 'spk-ja-n4-06-nakereba', 'create', '{"code":"n4-06-nakereba","level":"N4","number":6}'::jsonb, 'ai', 2006, 'pending'
