-- N4 · 7 · Giving and receiving
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-07-ageru-morau', 'lang-ja', ll.id, 'n4-07-ageru-morau', 7, 'あげます、もらいます、くれます', 'Giving and receiving', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-07-ageru-morau-s0', 'spk-ja-n4-07-ageru-morau', 0, 'explain', 'Three verbs for giving and receiving. First, {あげます}. It means "give", when the gift goes away from me, never to me. The person who receives takes {に}. {ともだちに ほんを あげます}. "I give a friend a book."', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s1', 'spk-ja-n4-07-ageru-morau', 1, 'prompt', 'How would you say "I give a friend a book"?', '友だちに本をあげます。', 'ともだち に ほん お あげます。', NULL),
  ('spk-ja-n4-07-ageru-morau-s2', 'spk-ja-n4-07-ageru-morau', 2, 'prompt', 'How would you say "I give a friend sushi"?', '友だちにすしをあげます。', 'ともだち に すし お あげます。', NULL),
  ('spk-ja-n4-07-ageru-morau-s3', 'spk-ja-n4-07-ageru-morau', 3, 'explain', 'A present is {プレゼント}.', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s4', 'spk-ja-n4-07-ageru-morau', 4, 'prompt', 'How would you say "I give a friend a present"?', '友だちにプレゼントをあげます。', 'ともだち に プレゼント お あげます。', NULL),
  ('spk-ja-n4-07-ageru-morau-s5', 'spk-ja-n4-07-ageru-morau', 5, 'prompt', 'How would you say "I will give a friend a present tomorrow"?', 'あした、友だちにプレゼントをあげます。', 'あした、ともだち に プレゼント お あげます。', NULL),
  ('spk-ja-n4-07-ageru-morau-s6', 'spk-ja-n4-07-ageru-morau', 6, 'prompt', 'How would you say "I gave a friend a present"?', '友だちにプレゼントをあげました。', 'ともだち に プレゼント お あげました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s7', 'spk-ja-n4-07-ageru-morau', 7, 'prompt', 'How would you say "What will you give your friend?"', '友だちに何をあげますか。', 'ともだち に なに お あげます か。', NULL),
  ('spk-ja-n4-07-ageru-morau-s8', 'spk-ja-n4-07-ageru-morau', 8, 'prompt', 'How would you say "I want to give a friend sushi"?', '友だちにすしをあげたいです。', 'ともだち に すし お あげたい です。', NULL),
  ('spk-ja-n4-07-ageru-morau-s9', 'spk-ja-n4-07-ageru-morau', 9, 'explain', 'Now the other direction. {もらいます} means "I receive". The person you receive from takes {に}. {ともだちに ほんを もらいます}. "I receive a book from a friend."', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s10', 'spk-ja-n4-07-ageru-morau', 10, 'prompt', 'How would you say "I receive a book from a friend"?', '友だちに本をもらいます。', 'ともだち に ほん お もらいます。', 'From can also be kara here. Both are right.'),
  ('spk-ja-n4-07-ageru-morau-s11', 'spk-ja-n4-07-ageru-morau', 11, 'prompt', 'How would you say "I received a book from the teacher"?', '先生に本をもらいました。', 'せんせい に ほん お もらいました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s12', 'spk-ja-n4-07-ageru-morau', 12, 'prompt', 'How would you say "I received a present from a friend"?', '友だちにプレゼントをもらいました。', 'ともだち に プレゼント お もらいました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s13', 'spk-ja-n4-07-ageru-morau', 13, 'prompt', 'How would you say "What did you receive from the teacher?"', '先生に何をもらいましたか。', 'せんせい に なに お もらいました か。', NULL),
  ('spk-ja-n4-07-ageru-morau-s14', 'spk-ja-n4-07-ageru-morau', 14, 'prompt', 'How would you say "I received tea from a friend. It was delicious."?', '友だちにおちゃをもらいました。おいしかったです。', 'ともだち に おちゃ お もらいました。おいしかった です。', NULL),
  ('spk-ja-n4-07-ageru-morau-s15', 'spk-ja-n4-07-ageru-morau', 15, 'explain', 'The third verb is {くれます}. It means someone gives something to ME. The giver is the one doing it, so the giver takes {が}. And I take {に}. {ともだちが わたしに ほんを くれました}.', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s16', 'spk-ja-n4-07-ageru-morau', 16, 'prompt', 'How would you say "A friend gave me a book"?', '友だちがわたしに本をくれました。', 'ともだち が わたし に ほん お くれました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s17', 'spk-ja-n4-07-ageru-morau', 17, 'prompt', 'How would you say "The teacher gave me a present"?', '先生がわたしにプレゼントをくれました。', 'せんせい が わたし に プレゼント お くれました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s18', 'spk-ja-n4-07-ageru-morau', 18, 'prompt', 'How would you say "A friend gave me sushi"?', '友だちがわたしにすしをくれました。', 'ともだち が わたし に すし お くれました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s19', 'spk-ja-n4-07-ageru-morau', 19, 'prompt', 'How would you say "What did the teacher give you?"', '先生が何をくれましたか。', 'せんせい が なに お くれました か。', 'Kureru works for things given to you as well as to me.'),
  ('spk-ja-n4-07-ageru-morau-s20', 'spk-ja-n4-07-ageru-morau', 20, 'explain', 'Notice that {くれます} and {もらいます} describe the same event from two sides. "A friend gave me sushi", or "I received sushi from a friend".', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s21', 'spk-ja-n4-07-ageru-morau', 21, 'prompt', 'How would you say "I received sushi from a friend"?', 'わたしは友だちにすしをもらいました。', 'わたし わ ともだち に すし お もらいました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s22', 'spk-ja-n4-07-ageru-morau', 22, 'explain', 'Because {くれます} already means "to me", Japanese usually leaves out {わたしに}.', NULL, NULL, NULL),
  ('spk-ja-n4-07-ageru-morau-s23', 'spk-ja-n4-07-ageru-morau', 23, 'prompt', 'How would you say "A friend in Japan gave me a book"?', '日本の友だちが本をくれました。', 'にほん の ともだち が ほん お くれました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s24', 'spk-ja-n4-07-ageru-morau', 24, 'prompt', 'How would you say "A friend gave me sushi, so I gave the friend tea"?', '友だちがすしをくれましたから、友だちにおちゃをあげました。', 'ともだち が すし お くれました から、ともだち に おちゃ お あげました。', NULL),
  ('spk-ja-n4-07-ageru-morau-s25', 'spk-ja-n4-07-ageru-morau', 25, 'prompt', 'How would you say "I intend to give a friend a present"?', '友だちにプレゼントをあげるつもりです。', 'ともだち に プレゼント お あげる つもり です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-07-ageru-morau')
ON CONFLICT (session_id, index) DO NOTHING;

INSERT INTO content_review_queue (id, language_id, target_table, target_id, change_type, proposed, origin, priority, status)
SELECT 'crq-spk-ja-n4-07-ageru-morau', 'lang-ja', 'speak_sessions', 'spk-ja-n4-07-ageru-morau', 'create', '{"code":"n4-07-ageru-morau","level":"N4","number":7}'::jsonb, 'ai', 2007, 'pending'
