-- N4 · 8 · If, and when
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-08-tara', 'lang-ja', ll.id, 'n4-08-tara', 8, '食べたら', 'If, and when', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-08-tara-s0', 'spk-ja-n4-08-tara', 0, 'explain', 'To say "if" or "when", take the plain past, the {た} form, and add {ら}. {たべたら}. "If I eat", or "when I have eaten". Then say what follows.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s1', 'spk-ja-n4-08-tara', 1, 'prompt', 'How would you say "When I have eaten, I go home"?', '食べたら、うちに帰ります。', 'たべたら、うち に かえります。', NULL),
  ('spk-ja-n4-08-tara-s2', 'spk-ja-n4-08-tara', 2, 'prompt', 'How would you say "When I have eaten sushi, I watch TV"?', 'すしを食べたら、テレビを見ます。', 'すし お たべたら、テレビ お みます。', NULL),
  ('spk-ja-n4-08-tara-s3', 'spk-ja-n4-08-tara', 3, 'prompt', 'How would you say "When I go to school, I read a book"?', '学校に行ったら、本を読みます。', 'がっこう に いったら、ほん お よみます。', NULL),
  ('spk-ja-n4-08-tara-s4', 'spk-ja-n4-08-tara', 4, 'explain', 'Verbs like {のむ} use {だ}, so {のんだら}.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s5', 'spk-ja-n4-08-tara', 5, 'prompt', 'How would you say "When I have drunk tea, I go to school"?', 'おちゃを飲んだら、学校に行きます。', 'おちゃ お のんだら、がっこう に いきます。', NULL),
  ('spk-ja-n4-08-tara-s6', 'spk-ja-n4-08-tara', 6, 'prompt', 'How would you say "When I have read this book, I give it to a friend"?', 'この本を読んだら、友だちにあげます。', 'この ほん お よんだら、ともだち に あげます。', NULL),
  ('spk-ja-n4-08-tara-s7', 'spk-ja-n4-08-tara', 7, 'prompt', 'How would you say "When I go home, I want to watch TV"?', 'うちに帰ったら、テレビを見たいです。', 'うち に かえったら、テレビ お みたい です。', NULL),
  ('spk-ja-n4-08-tara-s8', 'spk-ja-n4-08-tara', 8, 'prompt', 'How would you say "If I go to Japan, I want to eat sushi"?', '日本に行ったら、すしを食べたいです。', 'にほん に いったら、すし お たべたい です。', NULL),
  ('spk-ja-n4-08-tara-s9', 'spk-ja-n4-08-tara', 9, 'explain', 'Inside an if or when part, the person or thing doing it takes {が}, not {は}. {せんせいが きたら}.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s10', 'spk-ja-n4-08-tara', 10, 'prompt', 'How would you say "When the teacher comes, let''s read a book"?', '先生が来たら、本を読みましょう。', 'せんせい が きたら、ほん お よみましょう。', NULL),
  ('spk-ja-n4-08-tara-s11', 'spk-ja-n4-08-tara', 11, 'explain', 'For "if not", use the plain past of "not". {たべなかったら}.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s12', 'spk-ja-n4-08-tara', 12, 'prompt', 'How would you say "If I don''t eat, I cannot go"?', '食べなかったら、行くことができません。', 'たべなかったら、いく こと が できません。', NULL),
  ('spk-ja-n4-08-tara-s13', 'spk-ja-n4-08-tara', 13, 'prompt', 'How would you say "If you don''t come, I think the teacher will go home"?', '来なかったら、先生は帰ると思います。', 'こなかったら、せんせい わ かえる と おもいます。', NULL),
  ('spk-ja-n4-08-tara-s14', 'spk-ja-n4-08-tara', 14, 'explain', 'Describing words work too. For the {い} kind, the past is {たかかった}, so "if it is expensive" is {たかかったら}.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s15', 'spk-ja-n4-08-tara', 15, 'prompt', 'How would you say "If it is expensive, I don''t eat"?', '高かったら、食べません。', 'たかかったら、たべません。', NULL),
  ('spk-ja-n4-08-tara-s16', 'spk-ja-n4-08-tara', 16, 'prompt', 'How would you say "If it is delicious, I eat every day"?', 'おいしかったら、毎日、食べます。', 'おいしかったら、まいにち、たべます。', NULL),
  ('spk-ja-n4-08-tara-s17', 'spk-ja-n4-08-tara', 17, 'prompt', 'How would you say "If it is not expensive, I want to eat"?', '高くなかったら、食べたいです。', 'たかくなかったら、たべたい です。', NULL),
  ('spk-ja-n4-08-tara-s18', 'spk-ja-n4-08-tara', 18, 'explain', 'With a noun or a {しずか} word, use the past of {だ}, which is {だった}. {しずかだったら}.', NULL, NULL, NULL),
  ('spk-ja-n4-08-tara-s19', 'spk-ja-n4-08-tara', 19, 'prompt', 'How would you say "If it is quiet, I will read a book here"?', 'しずかだったら、ここで本を読みます。', 'しずか だったら、ここ で ほん お よみます。', NULL),
  ('spk-ja-n4-08-tara-s20', 'spk-ja-n4-08-tara', 20, 'prompt', 'How would you say "If tomorrow is Sunday, I will go to a friend''s home"?', 'あしたが日曜日だったら、友だちのうちに行きます。', 'あした が にちようび だったら、ともだち の うち に いきます。', NULL),
  ('spk-ja-n4-08-tara-s21', 'spk-ja-n4-08-tara', 21, 'prompt', 'How would you say "If this is water, you may drink it"?', 'これが水だったら、飲んでもいいです。', 'これ が みず だったら、のんでも いい です。', NULL),
  ('spk-ja-n4-08-tara-s22', 'spk-ja-n4-08-tara', 22, 'prompt', 'How would you say "If it is quiet here, let''s eat here"?', 'ここがしずかだったら、ここで食べましょう。', 'ここ が しずか だったら、ここ で たべましょう。', NULL),
  ('spk-ja-n4-08-tara-s23', 'spk-ja-n4-08-tara', 23, 'prompt', 'How would you say "What do you want to do when you go to Japan?"', '日本に行ったら、何をしたいですか。', 'にほん に いったら、なに お したい です か。', NULL),
  ('spk-ja-n4-08-tara-s24', 'spk-ja-n4-08-tara', 24, 'prompt', 'How would you say "When I go to Japan, I intend to go to a friend''s home"?', '日本に行ったら、友だちのうちに行くつもりです。', 'にほん に いったら、ともだち の うち に いく つもり です。', NULL),
  ('spk-ja-n4-08-tara-s25', 'spk-ja-n4-08-tara', 25, 'prompt', 'How would you say "If you eat it, I think it will be delicious"?', '食べたら、おいしいと思います。', 'たべたら、おいしい と おもいます。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-08-tara')
