-- N4 · 9 · Can do, the short way
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-09-potential', 'lang-ja', ll.id, 'n4-09-potential', 9, '読めます、食べられます', 'Can do, the short way', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-09-potential-s0', 'spk-ja-n4-09-potential', 0, 'explain', 'There is a shorter way to say "can". It changes the verb itself. For verbs like {たべる}, drop the final {る} and add {られます}. {たべられます}. "I can eat." In this session, use this short way every time.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s1', 'spk-ja-n4-09-potential', 1, 'prompt', 'How would you say "I can eat"?', '食べられます。', 'たべられます。', NULL),
  ('spk-ja-n4-09-potential-s2', 'spk-ja-n4-09-potential', 2, 'prompt', 'How would you say "I can eat sushi"?', 'すしを食べられます。', 'すし お たべられます。', NULL),
  ('spk-ja-n4-09-potential-s3', 'spk-ja-n4-09-potential', 3, 'explain', '{みる} works the same. {みられます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s4', 'spk-ja-n4-09-potential', 4, 'prompt', 'How would you say "I can watch TV here"?', 'ここでテレビを見られます。', 'ここ で テレビ お みられます。', NULL),
  ('spk-ja-n4-09-potential-s5', 'spk-ja-n4-09-potential', 5, 'explain', 'Other verbs change their last sound again, this time to the {え} sound. {よむ} becomes {よめる}, and the polite form is {よめます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s6', 'spk-ja-n4-09-potential', 6, 'prompt', 'How would you say "I can read a book"?', '本を読めます。', 'ほん お よめます。', NULL),
  ('spk-ja-n4-09-potential-s7', 'spk-ja-n4-09-potential', 7, 'explain', '{のむ} becomes {のめる}. {のめます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s8', 'spk-ja-n4-09-potential', 8, 'prompt', 'How would you say "I can drink tea"?', 'おちゃを飲めます。', 'おちゃ お のめます。', NULL),
  ('spk-ja-n4-09-potential-s9', 'spk-ja-n4-09-potential', 9, 'explain', '{いく} becomes {いける}. {いけます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s10', 'spk-ja-n4-09-potential', 10, 'prompt', 'How would you say "I can go to school"?', '学校に行けます。', 'がっこう に いけます。', NULL),
  ('spk-ja-n4-09-potential-s11', 'spk-ja-n4-09-potential', 11, 'explain', '{かえる} becomes {かえれる}. {かえれます}. {かく} becomes {かける}. {かけます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s12', 'spk-ja-n4-09-potential', 12, 'prompt', 'How would you say "I can go home"?', 'うちに帰れます。', 'うち に かえれます。', NULL),
  ('spk-ja-n4-09-potential-s13', 'spk-ja-n4-09-potential', 13, 'prompt', 'How would you say "I can write my name"?', '名前を書けます。', 'なまえ お かけます。', NULL),
  ('spk-ja-n4-09-potential-s14', 'spk-ja-n4-09-potential', 14, 'explain', '{はなす} becomes {はなせる}. {はなせます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s15', 'spk-ja-n4-09-potential', 15, 'prompt', 'How would you say "I can speak Japanese"?', '日本語を話せます。', 'にほんご お はなせます。', NULL),
  ('spk-ja-n4-09-potential-s16', 'spk-ja-n4-09-potential', 16, 'explain', '{くる} is special. It becomes {こられます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s17', 'spk-ja-n4-09-potential', 17, 'prompt', 'How would you say "I can come tomorrow"?', 'あした、来られます。', 'あした、こられます。', NULL),
  ('spk-ja-n4-09-potential-s18', 'spk-ja-n4-09-potential', 18, 'explain', 'For "cannot", the usual {ません}. {たべられません}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s19', 'spk-ja-n4-09-potential', 19, 'prompt', 'How would you say "I cannot eat"?', '食べられません。', 'たべられません。', NULL),
  ('spk-ja-n4-09-potential-s20', 'spk-ja-n4-09-potential', 20, 'prompt', 'How would you say "I cannot read a book"?', '本を読めません。', 'ほん お よめません。', NULL),
  ('spk-ja-n4-09-potential-s21', 'spk-ja-n4-09-potential', 21, 'prompt', 'How would you say "I cannot eat here"?', 'ここで食べられません。', 'ここ で たべられません。', NULL),
  ('spk-ja-n4-09-potential-s22', 'spk-ja-n4-09-potential', 22, 'prompt', 'How would you say "I cannot speak Japanese"?', '日本語を話せません。', 'にほんご お はなせません。', NULL),
  ('spk-ja-n4-09-potential-s23', 'spk-ja-n4-09-potential', 23, 'prompt', 'How would you say "Can you speak Japanese?"', '日本語を話せますか。', 'にほんご お はなせます か。', NULL),
  ('spk-ja-n4-09-potential-s24', 'spk-ja-n4-09-potential', 24, 'prompt', 'How would you say "Yes, I can speak it"?', 'はい、話せます。', 'はい、はなせます。', NULL),
  ('spk-ja-n4-09-potential-s25', 'spk-ja-n4-09-potential', 25, 'prompt', 'How would you say "No, I can''t speak it"?', 'いいえ、話せません。', 'いいえ、はなせません。', NULL),
  ('spk-ja-n4-09-potential-s26', 'spk-ja-n4-09-potential', 26, 'prompt', 'How would you say "What time can you come?"', '何時に来られますか。', 'なんじ に こられます か。', NULL),
  ('spk-ja-n4-09-potential-s27', 'spk-ja-n4-09-potential', 27, 'explain', 'With the short form, the thing you can do often takes {が} instead of {を}. {ほんが よめます}.', NULL, NULL, NULL),
  ('spk-ja-n4-09-potential-s28', 'spk-ja-n4-09-potential', 28, 'prompt', 'How would you say "I can read Japanese books"?', '日本語の本が読めます。', 'にほんご の ほん が よめます。', NULL),
  ('spk-ja-n4-09-potential-s29', 'spk-ja-n4-09-potential', 29, 'prompt', 'How would you say "Can you eat sushi?"', 'すしが食べられますか。', 'すし が たべられます か。', NULL),
  ('spk-ja-n4-09-potential-s30', 'spk-ja-n4-09-potential', 30, 'prompt', 'How would you say "I could not go yesterday"?', 'きのう、行けませんでした。', 'きのう、いけませんでした。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-09-potential')
ON CONFLICT (session_id, index) DO NOTHING;

