-- N4 · 10 · Putting it all together
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n4-10-review', 'lang-ja', ll.id, 'n4-10-review', 10, 'ぜんぶ、つかいましょう', 'Putting it all together', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N4'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n4-10-review-s0', 'spk-ja-n4-10-review', 0, 'explain', 'Everything comes together now. Casual talk, thinking, being able, intending, must, giving, if, and the short way to say can. Take your time.', NULL, NULL, NULL),
  ('spk-ja-n4-10-review-s1', 'spk-ja-n4-10-review', 1, 'prompt', 'How would you say, casually, "I didn''t go to school yesterday"?', 'きのう、学校に行かなかった。', 'きのう、がっこう に いかなかった。', NULL),
  ('spk-ja-n4-10-review-s2', 'spk-ja-n4-10-review', 2, 'prompt', 'How would you say, casually, "Did you eat sushi in Japan?"', '日本ですしを食べた？', 'にほん で すし お たべた？', NULL),
  ('spk-ja-n4-10-review-s3', 'spk-ja-n4-10-review', 3, 'prompt', 'How would you say "I think the sushi in Japan was delicious"?', '日本のすしはおいしかったと思います。', 'にほん の すし わ おいしかった と おもいます。', NULL),
  ('spk-ja-n4-10-review-s4', 'spk-ja-n4-10-review', 4, 'prompt', 'How would you say "I think the teacher can speak Japanese"?', '先生は日本語を話せると思います。', 'せんせい わ にほんご お はなせる と おもいます。', NULL),
  ('spk-ja-n4-10-review-s5', 'spk-ja-n4-10-review', 5, 'explain', '"But", at the start of a sentence, is {でも}.', NULL, NULL, NULL),
  ('spk-ja-n4-10-review-s6', 'spk-ja-n4-10-review', 6, 'prompt', 'How would you say "I can read Japanese books, but I cannot write"?', '日本語の本が読めます。でも、書けません。', 'にほんご の ほん が よめます。でも、かけません。', NULL),
  ('spk-ja-n4-10-review-s7', 'spk-ja-n4-10-review', 7, 'prompt', 'How would you say "I intend to go to Japan next year, so I must speak Japanese"?', '来年、日本に行くつもりですから、日本語を話さなければなりません。', 'らいねん、にほん に いく つもり です から、にほんご お はなさなければ なりません。', NULL),
  ('spk-ja-n4-10-review-s8', 'spk-ja-n4-10-review', 8, 'prompt', 'How would you say "A friend gave me a present, so I intend to give my friend sushi"?', '友だちがプレゼントをくれましたから、友だちにすしをあげるつもりです。', 'ともだち が プレゼント お くれました から、ともだち に すし お あげる つもり です。', NULL),
  ('spk-ja-n4-10-review-s9', 'spk-ja-n4-10-review', 9, 'prompt', 'How would you say "When I have eaten, I must read a book"?', '食べたら、本を読まなければなりません。', 'たべたら、ほん お よまなければ なりません。', NULL),
  ('spk-ja-n4-10-review-s10', 'spk-ja-n4-10-review', 10, 'prompt', 'How would you say "If it is quiet, may I read a book here?"', 'しずかだったら、ここで本を読んでもいいですか。', 'しずか だったら、ここ で ほん お よんでも いい です か。', NULL),
  ('spk-ja-n4-10-review-s11', 'spk-ja-n4-10-review', 11, 'prompt', 'How would you say "I received a book from the teacher, so I can read it at home"?', '先生に本をもらいましたから、うちで読めます。', 'せんせい に ほん お もらいました から、うち で よめます。', NULL),
  ('spk-ja-n4-10-review-s12', 'spk-ja-n4-10-review', 12, 'explain', 'The short can has a plain not as well. {いけない}.', NULL, NULL, NULL),
  ('spk-ja-n4-10-review-s13', 'spk-ja-n4-10-review', 13, 'prompt', 'How would you say "I think I cannot go to school tomorrow"?', 'あした、学校に行けないと思います。', 'あした、がっこう に いけない と おもいます。', NULL),
  ('spk-ja-n4-10-review-s14', 'spk-ja-n4-10-review', 14, 'prompt', 'How would you say "I have been to Japan once. It was beautiful."?', '日本にいちど行ったことがあります。きれいでした。', 'にほん に いちど いった こと が あります。きれい でした。', NULL),
  ('spk-ja-n4-10-review-s15', 'spk-ja-n4-10-review', 15, 'prompt', 'How would you say "What do you intend to do on Sunday?"', '日曜日は何をするつもりですか。', 'にちようび わ なに お する つもり です か。', NULL),
  ('spk-ja-n4-10-review-s16', 'spk-ja-n4-10-review', 16, 'prompt', 'How would you say "I intend to watch TV and read books, among other things"?', 'テレビを見たり、本を読んだりするつもりです。', 'テレビ お みたり、ほん お よんだり する つもり です。', NULL),
  ('spk-ja-n4-10-review-s17', 'spk-ja-n4-10-review', 17, 'prompt', 'How would you say "Please don''t eat here. I think the teacher will come."?', 'ここで食べないでください。先生は来ると思います。', 'ここ で たべない で ください。せんせい わ くる と おもいます。', NULL),
  ('spk-ja-n4-10-review-s18', 'spk-ja-n4-10-review', 18, 'prompt', 'How would you say, casually, "It is expensive, so I intend not to eat"?', '高いから、食べないつもりだ。', 'たかい から、たべない つもり だ。', NULL),
  ('spk-ja-n4-10-review-s19', 'spk-ja-n4-10-review', 19, 'prompt', 'How would you say "If you come at seven, let''s eat sushi"?', '七時に来たら、すしを食べましょう。', 'しちじ に きたら、すし お たべましょう。', NULL),
  ('spk-ja-n4-10-review-s20', 'spk-ja-n4-10-review', 20, 'prompt', 'How would you say "I must get up at six every day, so I sleep at ten"?', '毎日、六時におきなければなりませんから、十時にねます。', 'まいにち、ろくじ に おきなければ なりません から、じゅうじ に ねます。', NULL),
  ('spk-ja-n4-10-review-s21', 'spk-ja-n4-10-review', 21, 'prompt', 'How would you say "The restaurant in Japan was not expensive, so I think I can go every day"?', '日本のレストランは高くなかったですから、毎日、行けると思います。', 'にほん の レストラン わ たかくなかった です から、まいにち、いける と おもいます。', NULL),
  ('spk-ja-n4-10-review-s22', 'spk-ja-n4-10-review', 22, 'prompt', 'How would you say "When I go to Japan, I want to give a friend a present. I also want to eat sushi."?', '日本に行ったら、友だちにプレゼントをあげたいです。すしも食べたいです。', 'にほん に いったら、ともだち に プレゼント お あげたい です。すし も たべたい です。', NULL),
  ('spk-ja-n4-10-review-s23', 'spk-ja-n4-10-review', 23, 'prompt', 'How would you say "I received tea from a friend yesterday. I drank it, and it was delicious."?', 'きのう、友だちにおちゃをもらいました。飲みました。おいしかったです。', 'きのう、ともだち に おちゃ お もらいました。のみました。おいしかった です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n4-10-review')
ON CONFLICT (session_id, index) DO NOTHING;

